package br.com.gestao; import br.com.gestao.auth.*; import br.com.gestao.product.*; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.context.annotation.Bean; import org.springframework.security.crypto.password.PasswordEncoder; import java.math.BigDecimal;
@SpringBootApplication public class GestaoApplication{public static void main(String[]a){SpringApplication.run(GestaoApplication.class,a);} @Bean CommandLineRunner seed(AppUserRepository users,ProductRepository products,PasswordEncoder enc){return a->{if(users.findByEmail("admin@teste.com").isEmpty())users.save(new AppUser(null,"Administrador","admin@teste.com",enc.encode("123456"),Role.ADMIN));if(users.findByEmail("usuario@teste.com").isEmpty())users.save(new AppUser(null,"Operador","usuario@teste.com",enc.encode("123456"),Role.USER));if(products.count()==0){products.save(new Product(null,"P001","Notebook","Informática",new BigDecimal("2500"),new BigDecimal("3299.90"),8,3,true));products.save(new Product(null,"P002","Mouse sem fio","Acessórios",new BigDecimal("45"),new BigDecimal("89.90"),22,5,true));products.save(new Product(null,"P003","Teclado mecânico","Acessórios",new BigDecimal("160"),new BigDecimal("259.90"),4,4,true));}};}}
